 const centre=mm(sc(scale,scale,scale),tr(-.0715,-.0365,-.049));
 const popup={lid:[0,1.0,0],controls:[0,.98,0],chamber:[-.19,.26,-.14],
   fan:[-.10,.43,-.15],display:[.10,.23,0],supports:[0,.13,0],pcb:[0,.10,0],power:[.16,.17,0],battery:[0,.08,0]};
