  gl.uniform1f(uni.metal,part.metal);gl.uniform1f(uni.glow,part.group==='display'&&part.rgba[0]>.8?.12:0);
  const sensing=ease5((p-.716)/.016)*(1-ease5((p-.748)/.01));let emphasis=1;if(sensing>.001){const sensorGroup=terraSensorSelection===2?'sensors':'probes';emphasis=(part.group===sensorGroup?1:part.group==='case'?.25:.6);emphasis=lerp(1,emphasis,sensing*.54);}gl.uniform1f(uni.opacity,part.rgba[3]*weight*emphasis);
