if(gl&&program){
 // One finger spins the landing view around a fixed camera: horizontal drags
 // turn left/right, vertical drags look up/down. The eye never translates, and
 // a second touch is ignored so the spin never depends on a hidden gesture.
 let homeTouch=null;
 canvas.addEventListener('pointerdown',e=>{
  const homeLook=e.pointerType==='touch'&&document.body.classList.contains('mobile-home');
  if(homeTouch!==null||(homeLook&&window.__kiraSequence?.active)||window.ProjectStudy?.active||(e.pointerType==='touch'&&!homeLook)||(!homeLook&&document.body.classList.contains('hall-current')&&!['assembly','conveyor'].includes(document.body.dataset.hallStation)))return;
  canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');
  dragging=true;ptr=[e.clientX,e.clientY];
  if(homeLook)homeTouch=e.pointerId;
 });
 canvas.addEventListener('pointermove',e=>{
  if(homeTouch!==null){
   if(!document.body.classList.contains('mobile-home')){endTouch(e);return;}
   if(e.pointerId!==homeTouch)return;
   const dx=e.clientX-ptr[0];
   ptr=[e.clientX,e.clientY];
   if(!dx)return;
   // Positive hall yaw looks left, so a rightward drag reduces it. Keep the
   // left stop close to the starting desk view and the right stop at the room edge.
   orbitTY=clamp(orbitTY-dx*.006,-.90,.06);
   return;
  }
  if(!dragging)return;
  const hall=document.body.classList.contains('hall-current'),homeLook=e.pointerType==='touch'&&document.body.classList.contains('mobile-home');
  orbitTY+=clamp((e.clientX-ptr[0])*.007,-.19,.19);
  if(homeLook)orbitTY=clamp(orbitTY,-.90,.06);
  else if(hall)orbitTY=clamp(orbitTY,-.45,.45);
  orbitTX=clamp(orbitTX+(e.clientY-ptr[1])*.005,homeLook?-.2:hall?-.3:-.55,homeLook?.2:hall?.3:.55);
  ptr=[e.clientX,e.clientY];
 });
 function endTouch(e){
  if(homeTouch!==null){
   if(e.pointerId!==homeTouch)return;
   homeTouch=null;dragging=false;canvas.classList.remove('dragging');
   return;
  }
  dragging=false;canvas.classList.remove('dragging');
 }
 phoneUIQuery.addEventListener('change',()=>{const id=homeTouch;homeTouch=null;if(id!==null&&canvas.hasPointerCapture(id))canvas.releasePointerCapture(id);dragging=false;orbitTX=orbitTY=0;canvas.classList.remove('dragging');});
 for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,endTouch);
}
